const select=document.querySelector('#animal-select');select.innerHTML=ANIMALS.map(a=>'<option value="'+a.id+'">'+a.id+' — '+a.name+'</option>').join('');
const params=new URLSearchParams(location.search),wanted=Number(params.get('id')||1);select.value=String(ANIMALS.some(a=>a.id===wanted)?wanted:1);if(params.get('from')==='ar')document.querySelector('#back').href='scan.html';
const scene=document.createElement('a-scene');scene.setAttribute('embedded','');scene.setAttribute('xr-mode-ui','enabled: false');scene.setAttribute('renderer','antialias: true; colorManagement: true');scene.setAttribute('background','color: #eaf0e2');
scene.innerHTML='<a-entity camera="fov: 43" position="0 0 3.5" look-controls="enabled: false" wasd-controls="enabled: false"></a-entity><a-light type="ambient" intensity="0.8"></a-light><a-light type="directional" position="-2 3 4" intensity="0.7"></a-light><a-light type="directional" position="3 1 -2" intensity="0.35"></a-light>';
for(const a of ANIMALS){const holder=document.createElement('a-entity');holder.id='animal-model-'+a.id;const model=document.createElement('a-entity');model.dataset.animalId=a.id;model.setAttribute('rotation','0 '+(a.modelYaw||35)+' 0');model.setAttribute('fit-animal','size: 1.8; pivot: center');model.dataset.modelSource=a.model;model.addEventListener('animal-ready',()=>{if(Number(select.value)===a.id)document.querySelector('#preview-error').textContent='';});model.addEventListener('model-error',()=>{model.dataset.failed='true';if(Number(select.value)===a.id)document.querySelector('#preview-error').textContent='Không tải được mô hình. Kiểm tra file GLB.';});holder.append(model);scene.append(holder);}
document.querySelector('#scene-container').append(scene);
function pick(){const id=Number(select.value);scene.querySelectorAll('[id^="animal-model-"]').forEach(h=>h.object3D.visible=h.id==='animal-model-'+id);const model=document.querySelector('#animal-model-'+id+' [data-model-source]');if(!model.hasAttribute('gltf-model'))model.setAttribute('gltf-model',model.dataset.modelSource);document.dispatchEvent(new CustomEvent('ar-tracking',{detail:{found:true,id}}));document.querySelector('#preview-error').textContent=model.dataset.failed?'Không tải được mô hình.':model.dataset.ready?'':'Đang tải mô hình…';document.querySelector('#open-ar').href='scan.html';}
select.addEventListener('change',pick);pick();